"""Build an eight-page evidence deck and status report from measured CP4 artifacts."""
import html
import json
from pathlib import Path
from .audit import facts

ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'cp4/public'
STYLE='''*{box-sizing:border-box}body{margin:0;background:#dedfd6;color:#223c2c;font-family:Arial,sans-serif}.slide{width:1280px;height:720px;position:relative;background:#f7f5ed;padding:52px 66px;margin:28px auto;overflow:hidden;break-after:page}.eyebrow{font-size:15px;letter-spacing:2px;text-transform:uppercase;color:#64715d}h1{font-size:47px;line-height:1.12;max-width:1100px;margin:24px 0 30px;letter-spacing:-1.4px}h2{font-size:27px;margin:0 0 14px}p,li{font-size:23px;line-height:1.45}p{margin:12px 0}.cols{display:grid;grid-template-columns:1fr 1fr;gap:32px}.box{padding:26px;background:#eceee2;border:1px solid #d3d9c7;border-radius:14px}.big{font-size:86px;font-weight:700;letter-spacing:-4px}.accent{color:#ad4d2d}.sub{font-size:19px;color:#59664f}.footer{position:absolute;left:66px;right:66px;bottom:24px;font-size:13px;color:#65715c;border-top:1px solid #ccd3c0;padding-top:12px;line-height:1.4}.page{float:right;font-weight:bold}.flow{display:flex;gap:18px;align-items:stretch;margin:30px 0}.flow .box{flex:1;font-size:22px}.flow strong{display:block;font-size:29px;margin-bottom:14px}table{border-collapse:collapse;width:100%;font-size:21px}th,td{text-align:left;border-bottom:1px solid #cfd6c4;padding:14px 9px}th{font-size:17px;text-transform:uppercase;color:#66725b}.bar{height:21px;background:#dce2d2;border-radius:8px;overflow:hidden;margin:8px 0 20px}.bar i{display:block;height:100%;background:#607a42}.tag{display:inline-block;background:#dfe8d3;padding:9px 14px;border-radius:6px;font-size:18px}.quote{font-size:27px;line-height:1.5;border-left:5px solid #b0633d;padding-left:22px}.full{max-width:1060px}.small{font-size:18px}.demo{height:320px;width:100%;object-fit:cover;object-position:top;border:1px solid #cbd3c0;border-radius:10px}a{color:#355d30}@page{size:13.333333in 7.5in;margin:0}@media print{body{background:white}.slide{margin:0}}'''
def main():
    f=facts();OUT.mkdir(exist_ok=True,parents=True)
    budget=f['budget'];total=f"${budget['usd']:.6f}"
    slides=[
      ('Người dùng & pain','Nhu cầu có tín hiệu, giả thuyết chưa qua ngưỡng.', '''<div class="cols"><div class="box"><div class="big accent">11/19</div><h2>58% gặp vấn đề đúng lát cắt</h2><p>Chuỗi, quán chăng khách hoặc tốn thời gian đọc review.</p><p class="sub">Dưới ngưỡng 60%; 19 mẫu hợp lệ chưa đủ 20. Phỏng vấn: 0/3.</p></div><div><p class="quote">“Giá có sẵn, ảnh đúng món thật”</p><p class="sub">Khảo sát ẩn danh P18 · evidence/summary.md</p><p>15/19 muốn cách chọn khác; 11/19 gặp “đồ ăn không ngon”, ngoài khả năng phân loại hiện tại.</p><p class="sub">Chưa xác nhận vai, khu vực hoặc số phút mất mỗi lần.</p></div></div>''','evidence/summary.md; evidence/survey/results.csv; evidence/hypothesis.md'),
      ('Vì sao chọn bài này','Thu hẹp vào tín hiệu quán và menu có nguồn.', '''<div class="cols"><div><div class="big">422</div><h2>địa điểm nguồn hiện có</h2><p>364 ở Gia Lâm, 58 ở Văn Giang. Chưa phủ đủ các quận trong spec.</p><p class="tag">150 quán ShopeeFood · 4.308 dòng món</p></div><div class="box"><h2>Quyết định của nhóm</h2><p>Chọn phân loại quán kèm lý do vì có thể tra lại bằng công cụ.</p><p class="small">Gợi ý theo khẩu vị cần dữ liệu cá nhân. Tóm tắt review chưa trực tiếp giải việc nhận diện chuỗi.</p><p class="small">Impact tiết kiệm thời gian chưa được đo; 5–10 phút trong spec là tự ước tính.</p></div></div>''','spec.md §2; data/processed/places.csv; shopee_stores.csv; shopee_menu.csv'),
      ('Giải pháp','Workflow cố định; thiếu căn cứ thì chưa kết luận.', '''<div class="flow"><div class="box"><strong>Tra dữ liệu</strong>get_place<br>lookup_chain<br>get_reviews</div><div class="box"><strong>Model</strong>Đề xuất nhãn<br>Độ chắc<br>Token usage thật</div><div class="box"><strong>Chặn bằng luật</strong>Nguồn chuỗi<br>Review tối thiểu<br>Chống ép nhãn</div><div class="box"><strong>Người quyết</strong>Nhãn + lý do<br>Chưa chắc →<br>nháp chờ kiểm</div></div><p>412 địa điểm lên UI sau khi tách 10 điểm hỗ trợ tài xế.</p><p class="sub">17 địa điểm có kết quả AI đã lưu. Các địa điểm còn lại không được gán nhãn giả; UI tìm kiếm không gọi model trực tiếp.</p>''','spec.md §4; cp3/agent.py; cp4/agent.py; web-demo/data/live_manifest.json'),
      ('Demo thực tế','Một ca nhận diện chuỗi, một ca chưa đủ căn cứ.', '''<div class="cols"><div><img class="demo" src="ui-desktop.png" alt="Ảnh chụp UI tích hợp dữ liệu thật"><p class="sub">Bản đồ thật + menu online, giao diện gốc giữ nguyên.</p></div><div class="box"><h2>B08 · Haidilao → chain</h2><p class="small">Nguồn chính thức được thêm vào registry phụ; lý do và URL có trong output.</p><h2>B11 · Bếp Của Nhung → unsure</h2><p class="small">0 review; có menu và giá online để tự đối chiếu. Không kết luận local khi thiếu căn cứ.</p><p class="small">Dự phòng: demo-backup.webm<br>Thử lạ: python -m cp4.run</p></div></div>''','eval/run-3.csv B08, B11; traces/run-3.jsonl; screenshot UI qua Playwright'),
      ('Đánh giá','Cải tiến +3 câu; chất lượng tổng thể vẫn cần nâng.', '''<div class="cols"><div><p>Baseline run-1 · 12/20 · 60%</p><div class="bar"><i style="width:60%"></i></div><p>Đổi model run-2 · 12/20 · 60%</p><div class="bar"><i style="width:60%"></i></div><p><b>CP4 run-3 · 15/20 · 75% (nháp)</b></p><div class="bar"><i style="width:75%"></i></div><p class="sub">Sửa B08, B12, B20; không sửa benchmark hay expected.</p></div><div class="box"><h2>So với chuẩn đóng băng</h2><p class="small">Nhãn câu thường: 5/9 = 55,6% &lt; 75%.</p><p class="small">Unsure đúng + có flag: 5/5 = 100% ≥ 90%.</p><p class="small">Từ chối/chèn lệnh: 4/4 = 100%.</p><p class="small">Grounded reason: 15/15 câu có nhãn khớp bằng chứng trace (nháp).</p><p class="small accent">5 câu local vẫn trượt. Cần người thứ hai duyệt; B16 chưa gợi ý được quán.</p></div></div>''','eval/run-1.csv; run-2.csv; run-3@20261128-093712; cp4/results/run-3-graded-draft.csv; metric_spec.yaml'),
      ('Chi phí khi dùng thật','Chi phí token nhỏ; chưa bao gồm vận hành và data.', '''<p><span class="tag">50 phiên · 87 lượt hỏi · 0 lỗi · token từ API usage</span></p><table><thead><tr><th>Kịch bản giá</th><th>USD / phiên</th><th>USD / task đạt*</th><th>USD / tháng · 300 người*</th></tr></thead><tbody><tr><td>gpt-6-luna · đã chạy</td><td>0,00015</td><td>0,00020</td><td>0,7579</td></tr><tr><td>gpt-6.1-sol · chỉ áp giá</td><td>0,0030</td><td>0,0040</td><td>15,16</td></tr></tbody></table><p class="small">100 / 300 / 1.000 người: Luna $0,2526 / $0,7579 / $2,53 mỗi tháng.</p><p class="small">*Người dùng, số phiên/tháng là tự ước tính. Task đạt dùng tỷ lệ nháp 75%, chưa phải hiệu quả ngoài đời. Model thứ hai áp giá trên token Luna, chưa đo chất lượng.</p><p class="sub">Tổng batch CP4: COST · trần được duyệt $1. Chưa tính thuế, hosting, crawl/review và thời gian người kiểm.</p>'''.replace('COST',total),'cost/simulate-1@20261128-094156; cost/simulate-1-summary.md; cp4/personas.yaml; API pricing 28/11/2026'),
      ('Kết luận','ITERATE — có bản chạy thật, chưa đủ bằng chứng để mở rộng.', '''<div class="cols"><div class="box"><h2>Đã có bằng chứng kỹ thuật</h2><p>20 câu qua API, 0 lỗi.<br>50 phiên mô phỏng, 0 lỗi.<br>Menu đầy đủ ở 138/150 quán.</p><p class="small">Lý do và nguồn hiển thị; dữ liệu thiếu không bị thay bằng mẫu minh họa.</p></div><div><h2>Chưa thể kết luận đạt toàn bộ CP4</h2><p>58% pain &lt; 60%, mẫu 19 &lt; 20.<br>5/9 nhãn thường &lt; 75%.<br>Review thật: 0.<br>Người chấm thứ hai: chưa có.</p><p class="sub">Chi phí thấp không thay thế bằng chứng người dùng và độ đúng.</p></div></div>''','evidence/summary.md; cp4/results/run-3-graded-draft.csv; cost/simulate-1.csv; shopee_stores.csv'),
      ('Thêm một tuần','Ưu tiên dữ liệu và kiểm chứng trước khi thêm tính năng.', '''<div class="flow"><div class="box"><strong>01 · Bằng chứng</strong><p class="small">Đủ ≥20 người đúng đối tượng, ≥3 phỏng vấn thật; đo thời gian chọn quán trước/sau.</p></div><div class="box"><strong>02 · Dữ liệu</strong><p class="small">Thu ≥3 review cho 150 quán; kiểm tra nguồn, không lưu tên tác giả. Ghép 140 menu còn thiếu tọa độ.</p></div><div class="box"><strong>03 · Kiểm định</strong><p class="small">Người thứ hai chấm ≥5 output; ưu tiên 5 lỗi local và B16. Chạy máy khác, phân công thuyết trình.</p></div></div><p class="tag">Giữ nguyên chuẩn đạt và các lượt đã chạy.</p><p class="sub">Bộ nộp bổ sung: cp4/README.md · status.html · demo-slides.pdf · demo-backup.webm</p>''','spec.md §7; slides/outline.md; eval/report.md; cp4/README.md')
    ]
    body=''.join(f'<section class="slide" id="slide-{i}"><div class="eyebrow">Vinnovators · CP4 / {html.escape(k)}</div><h1>{title}</h1>{content}<footer class="footer"><span class="page">{i} / 8</span>Nguồn: {html.escape(source)}</footer></section>' for i,(k,title,content,source) in enumerate(slides,1))
    (OUT/'slides.html').write_text('<!doctype html><html lang="vi"><meta charset="utf-8"><title>Vinnovators · CP4</title><style>'+STYLE+'</style><body>'+body+'</body></html>',encoding='utf8')
    status=f'''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hồ sơ CP4</title><style>body{{font:17px/1.65 Arial;max-width:1000px;margin:36px auto;padding:0 20px;background:#f7f5ed;color:#243b2a}}h1{{font-size:40px}}table{{border-collapse:collapse;width:100%}}th,td{{padding:12px;border-bottom:1px solid #ccd3c0;text-align:left}}a{{color:#345b2c}}.box{{padding:20px;background:#e8eddf;border-radius:12px}}video{{width:100%}}code{{overflow-wrap:anywhere}}img{{max-width:100%}}</style><body><a href="/web-demo/live.html">← Mở bản tích hợp</a><h1>CP4 · bản chạy thật & giới hạn</h1><p class="box">Kết luận: <b>ITERATE</b>. Đã hoàn thành phần kỹ thuật và hồ sơ bổ sung. Chưa đủ xác nhận người dùng, review thật và người chấm độc lập để tuyên bố đạt toàn bộ CP4.</p><p><a href="slides.html">8 slide HTML</a> · <a href="demo-slides.pdf">PDF offline</a> · <a href="/web-demo/menu.html">150 quán & toàn bộ menu</a></p>
<h2>Dữ liệu nối vào UI</h2><p>422 địa điểm nguồn → 412 điểm lên bản đồ; tách 10 điểm hỗ trợ tài xế. Gia Lâm 356, Văn Giang 56; các quận khác chưa có data. Có 17 địa điểm được AI đánh giá và 395 chưa được đánh giá; không dùng quán minh họa để lấp chỗ trống. 150 quán ShopeeFood, 4.308 dòng món; 138 menu đầy đủ, 12 chưa trả menu đọc được. 10 quán ghép menu với tọa độ, 140 giữ link tìm địa chỉ. Giá là giá đặt online tại ngày thu, có nguồn và thời điểm từng món.</p>
<h2>Đánh giá trước / sau — bản chấm nháp</h2><table><tr><th>Lượt</th><th>Đạt</th><th>Thông tin</th></tr><tr><td>run-1@20261128-082514</td><td>12/20 · 60%</td><td>Baseline; người thứ hai chưa duyệt</td></tr><tr><td>run-2@20261128-090411</td><td>12/20 · 60%</td><td>Đổi model, chưa cải tiến</td></tr><tr><td>run-3@20261128-093712</td><td>15/20 · 75%</td><td>Registry Haidilao + loại điểm hỗ trợ + từ chối ép nhãn</td></tr></table>
<p>Metric nhãn thường 5/9 (55,6%) chưa đạt 75%; unsure routing 5/5 (100%) đạt ≥90%; từ chối/chèn lệnh 4/4 (100%). Grounded reason 15/15 câu có nhãn (16 verdicts) khớp trường bằng chứng đọc đủ trong trace, bản chấm nháp; không suy diễn phần công cụ bị cắt ngắn. Lượt mới không lỗi API, 16 model calls. Năm ca local B01–04, B13 còn unsure vì 0 review; giữ luật thay vì đổi expected. B16 chưa gợi ý được quán: chấm theo tiêu chí hẹp giống baseline, cần người duyệt xem lại. Nháp nằm trong cp4/results/, các CSV lượt gốc không sửa.</p>
<h2>Chi phí</h2><p>50 phiên / {f['simulation_turns']} lượt hỏi, 0 lỗi; {f['simulation_tokens_in']:,} input tokens, {f['simulation_tokens_out']:,} output tokens từ API usage. Trung bình Luna $0,00015/phiên; $0,00020/task đạt (dùng tỷ lệ nháp 75%). Ba kịch bản 100 / 300 / 1.000 người: $0,2526 / $0,7579 / $2,53 mỗi tháng. Người dùng, số phiên/tháng và số lượt/phiên là tự ước tính, chưa đo hành vi sử dụng app.</p>
<p>Kịch bản giá thứ hai gpt-6.1-sol áp lên token Luna: $0,0030/phiên và $5,05 / $15,16 / $50,52 mỗi tháng. Không phải đo chất lượng model thứ hai. Chỉ tính token, chưa gồm thuế, hạ tầng, thu review và người kiểm. Nguồn giá Standard ngày 28/11/2026: <a href="https://developers.openai.com/api/docs/models/gpt-6-luna">gpt-6-luna</a>, <a href="https://developers.openai.com/api/docs/pricing">bảng giá OpenAI</a>.</p><p><b>Tổng batch CP4: {total}</b> / trần $1, {budget['calls']} model calls. Đây là phép tính từ usage, không phải hóa đơn nhà cung cấp.</p>
<h2>Video dự phòng</h2><video src="demo-backup.webm" controls preload="metadata"></video><p>Ghi thao tác thật trên UI local bằng Playwright. UI hiển thị đầu ra đã lưu; video không phải quay chat gọi API trực tiếp.</p>
<h2>Phần cần người thật</h2><p>Khảo sát 22 lượt gửi, 19 hợp lệ; pain 11/19 = 58% &lt; 60%, phỏng vấn 0/3. Chưa xác nhận vai và khu vực, chưa đo số phút. Review thật 0/450 mục tiêu. Cần chấm độc lập, xác nhận nhãn chuẩn, bổ sung dữ liệu cho quận còn thiếu, điền phòng/zone, phân công nói, reflection và chạy trên máy khác. Không bịa dữ kiện để đánh dấu hoàn thành.</p>
<h2>Chạy lại từ repo</h2><p><code>python -m cp4.server</code> để xem UI. Kiểm tra: <code>python -m cp4.audit</code>, <code>python -m cp4.run check</code>. File khung gốc, metric, benchmark và các lượt cũ giữ nguyên. Chi tiết lệnh và giới hạn ở <code>cp4/README.md</code>.</p></body></html>'''
    (OUT/'status.html').write_text(status,encoding='utf8')
    (ROOT/'cp4/results/audit.json').write_text(json.dumps(f,ensure_ascii=False,indent=2),encoding='utf8')
    print('Generated status.html, slides.html and results/audit.json')
if __name__=='__main__':main()
